CREATE POLICY "Users can read own note images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'note-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can upload own note images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'note-images' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can delete own note images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'note-images' AND auth.uid()::text = (storage.foldername(name))[1]);